"""Verified same-epoch Stem comparison; new observations only, no model execution."""
from pathlib import Path
import base64,hashlib,json
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'outputs'
MAIN=OUT/'stem_component12_20261011_v1';REF=OUT/'native_stem_scratch12_20261011_v3';QUEUE=OUT/'stem_component_queue_pulse_20261011_v2'
PAYLOADS=json.loads("{\"reference\":{\"1\":{\"base64\":\"\",\"expected_sha256\":\"4ca30da171e63ed46b3ba0995feaecb2d7871f606085c771d5909d2b0e469caf\",\"expected_bytes\":3038},\"2\":{\"base64\":\"\",\"expected_sha256\":\"7385c6ee4118eee5fe4629c4c575f4901be33e89c2d4761a5c202ef578b8d30e\",\"expected_bytes\":3037}},\"queue\":{\"1\":{\"base64\":\"\",\"sha256\":\"051720d3e5c011bcfb5108c14857c53cddfb9028edb31dc95326c5563297a08b\",\"bytes\":1468},\"2\":{\"base64\":\"\",\"sha256\":\"1c890429b0fca3e96ae17945285fa7b0d832e072bc4ae128fe1908b397a63620\",\"bytes\":1468}}}")
read=lambda p:json.loads(Path(p).read_bytes())
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def write(p,v):
    with Path(p).open('x',encoding='utf8') as f:json.dump(v,f,ensure_ascii=False,indent=2,allow_nan=False)
observations={}
for kind,folder,version in [('reference',REF,6),('queue',QUEUE,2)]:
    observations[kind]={};transport={}
    for seed in (1,2):
        d=PAYLOADS[kind][str(seed)];b=base64.b64decode(d['base64'],validate=True)
        expected_sha=d.get('expected_sha256',d.get('sha256'));expected_bytes=d.get('expected_bytes',d.get('bytes'))
        assert len(b)==expected_bytes and hashlib.sha256(b).hexdigest()==expected_sha
        name=(f'compact_payload_seed{seed}_v{version}.json' if kind=='reference' else f'remote_observation_seed{seed}_v{version}.json')
        with (folder/name).open('xb') as f:f.write(b)
        observations[kind][seed]=json.loads(b)
        transport[str(seed)]=dict(file=name,bytes=len(b),sha256=expected_sha,status='PASS_EXACT_REMOTE_BYTES_AND_SHA256')
    write(folder/(f'compact_transport_v{version}.json' if kind=='reference' else f'observation_transport_v{version}.json'),transport)
snapshot=read(MAIN/'training_observation_v21.json');verified=read(MAIN/'training_observation_v21_transport_verification.json')
progress=read(MAIN/'progress_v21.json')
assert progress['snapshot_sha256']==sha(MAIN/'training_observation_v21.json')==verified['verified_snapshot_sha256']
ref=observations['reference']
for seed in (1,2):
    assert ref[seed]['code_sha256_verified'] and not ref[seed]['failures']
    assert ref[seed]['runtime']['first100_parity.json']['all100_rows_exact']
    assert 0<=ref[seed]['completed_epochs']<=12
    assert all(p['same_live'] for p in ref[seed]['processes'].values())
write(REF/'compact_observation_v6.json',{str(s):ref[s] for s in (1,2)})
pairs=[]
for seed in (1,2):
    r=ref[seed];e=r['completed_epochs'];random=r['latest_metrics'];assert random['epoch']==e-1
    full=next(m for m in snapshot[f'seed{seed}']['jobs']['original_stem']['metrics'] if m['epoch']==e-1)
    a,b=full['test_coco_eval_bbox'],random['test_coco_eval_bbox']
    pairs.append(dict(seed=seed,epoch=e,enhanced_AP=100*a[0],random_native_AP=100*b[0],delta_AP_pp=100*(a[0]-b[0]),enhanced_APs=100*a[3],random_native_APs=100*b[3],delta_APs_pp=100*(a[3]-b[3])))
comparison=dict(status='ANALYZED_DESCRIPTIVE_SAME_EPOCH_EARLY_LOGS',current_S_pairs=pairs,
    full_snapshot_sha256=sha(MAIN/'training_observation_v21.json'),random_native_observation_sha256=sha(REF/'compact_observation_v6.json'),
    all_seeds_preserved=True,fixed12_efficacy_established=False,root_cause_established=False,
    interpretation='At epoch3, enhanced Stem gains AP/APs on seed2 and loses on seed1. Comparing the enhanced latest epoch9/10 with random native epoch3 would mix training duration. Fixed12 remains pending.',
    new_model_forwards=0,new_optimizer_updates=0)
write(MAIN/'same_epoch_random_native_comparison_v3.json',comparison)
rs=read(REF/'execution_state_v4.json')
rs.update(supersedes='execution_state_v4.json',evidence='compact_observation_v6.json',transport_verification='compact_transport_v6.json exact SHA256 and byte length verified',
    completed_epochs={str(s):ref[s]['completed_epochs'] for s in (1,2)},optimizer_updates={str(s):ref[s]['runtime']['training_audit_live.json']['actual_optimizer_steps'] for s in (1,2)},
    latest_live_processes={str(s):ref[s]['processes'] for s in (1,2)})
write(REF/'execution_state_v5.json',rs)
queue=observations['queue']
for seed in (1,2):
    q=queue[seed]
    assert q['helper']['same_live'] and q['conductor']['same_live'] and q['conductor']['state']=='T' and q['reference']['same_live']
    assert q['code_SHA_verified'] and q['component_SHA_verified'] and q['failure'] is None and not q['pulses']
qs=read(QUEUE/'execution_state_v1.json')
qs.update(supersedes='execution_state_v1.json',evidence='remote_observation_seed1/2_v2.json',helpers={str(s):queue[s]['helper'] for s in (1,2)},queued_arms_started_by_helper=0)
write(QUEUE/'execution_state_v2.json',qs)
state=read(MAIN/'execution_state_v16.json')
full_epochs={f'seed{s}':len(snapshot[f'seed{s}']['jobs']['original_stem']['metrics']) for s in (1,2)}
control_epochs={f'{arm}_seed{s}':len(snapshot[f'seed{s}']['jobs'][arm]['metrics']) for s in (1,2) for arm in ('detail_lowres','highfreq_rgb')}
state.update(supersedes='execution_state_v16.json',evidence='training_observation_v21.json',baseline_comparison='progress_v21.json',
    reference_state='../native_stem_scratch12_20261011_v3/execution_state_v5.json',queue_helper_state='../stem_component_queue_pulse_20261011_v2/execution_state_v2.json',
    latest_full_completed_epochs=full_epochs,latest_active_control_completed_epochs=control_epochs,new_reference_epochs={f'seed{s}':ref[s]['completed_epochs'] for s in (1,2)},
    same_epoch_reference_comparison='same_epoch_random_native_comparison_v3.json',
    latest_full_vs_same_epoch_pretrained_BASE='Enhanced full seed1 epoch9, seed2 epoch10; both AP/APs below cached same-epoch pretrained BASE. Random-native comparison remains seed-dependent at same epoch3.',
    finding='Both scratch references have completed3, training4. Seed2 shows positive enhanced-vs-random AP/APs at same epoch3; seed1 negative. All8 current trainers live; pending4 queued trainers have not started.',
    fixed12_complete=False,current_goal_turn='progress',no_progress_streak=0,goal_complete=False,
    next='Complete exact12 runs and frozen EMA replay; inspect actual topk selection and geometry at fixed12 before assigning the mechanism. Do not compare unmatched epochs or retrain BASE.')
for s in (1,2):
    state['current_live_trainers'][f'seed{s}']={a:snapshot[f'seed{s}']['jobs'][a]['processes'] for a in ('original_stem','detail_lowres','highfreq_rgb')}
    assert all(p['same_live'] for ps in state['current_live_trainers'][f'seed{s}'].values() for p in ps)
write(MAIN/'execution_state_v17.json',state)
full=read(OUT/'original_stem12_20261011_v1/execution_state_v19.json')
full.update(supersedes='execution_state_v19.json',authoritative_state='../stem_component12_20261011_v1/execution_state_v17.json')
write(OUT/'original_stem12_20261011_v1/execution_state_v20.json',full)
print(json.dumps(dict(status='PASS_VERIFIED_SAME_EPOCH3_COMPARISON',pairs=pairs,full_completed_epochs=full_epochs,reference_completed_epochs={s:ref[s]['completed_epochs'] for s in (1,2)},all8_trainers_live=True,queued_arms_started=0),ensure_ascii=False))

